/** Isolated foreground-only Camera2 observability. Never stores images or claims a tracked pen. */
public final class OpticalCameraActivity extends Activity {
 private static final String HEADSET="horizonos.permission.HEADSET_CAMERA";
 private static final CameraCharacteristics.Key<Integer> SOURCE=new CameraCharacteristics.Key<>("com.meta.extra_metadata.camera_source",Integer.class);
 private static final CameraCharacteristics.Key<Integer> POSITION=new CameraCharacteristics.Key<>("com.meta.extra_metadata.position",Integer.class);
 private final Handler ui=new Handler(Looper.getMainLooper());
 private HandlerThread thread;private Handler worker;private CameraManager manager;private TextView status;
 private volatile boolean destroying=false;private int pendingOpens=0;
 private volatile boolean foreground=false;private volatile long generation=0;private volatile boolean capturing=false;
 private CheckBox markerMode;private EditText markerIdInput,markerSizeInput;private volatile Integer configuredMarkerId=null;private volatile double configuredMarkerSide=0;
 private MarkerPoseEstimator markerEstimator;private CameraCharacteristics captureCharacteristics;private final TreeMap<Long,TotalCaptureResult> matchedResults=new TreeMap<>();
 private CameraDevice camera;private CameraCaptureSession session;private ImageReader reader;
 private JSONObject receipt=new JSONObject();private JSONArray frames=new JSONArray();private long startNs,lastProcessedNs;private int received=0,processed=0;private JSONObject latestResult=new JSONObject();
 private final Runnable deadline=()->stop("completed-deadline");
 private final Runnable poseFreshness=new Runnable(){public void run(){if(!capturing)return;worker.post(()->{if(capturing&&markerEstimator!=null&&SystemClock.elapsedRealtimeNanos()-lastProcessedNs>1000000000L){try{receipt.put("currentMarkerPose",JSONObject.NULL);receipt.put("markerUnavailableReason","No fresh analyzed image within1s");persist();show("Marker unavailable: no fresh analyzed image");}catch(JSONException ignored){}}});ui.postDelayed(this,500);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);manager=getSystemService(CameraManager.class);thread=new HandlerThread("bounded-optical-analysis");thread.start();worker=new Handler(thread.getLooper());
  LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(24,24,24,24);
  TextView title=new TextView(this);title.setText("Muse optical observability — experimental");title.setTextSize(24);layout.addView(title);
  TextView note=new TextView(this);note.setText("Public passthrough RGB cameras only. Bright blobs are not identified Muse LEDs or a pose. No room frames are saved. Capture ends after 20 seconds or when this app backgrounds.");layout.addView(note);
  Button permission=new Button(this);permission.setText("Request camera permission / enumerate");permission.setOnClickListener(v->requestAndEnumerate());layout.addView(permission);
  markerMode=new CheckBox(this);markerMode.setText("Optional known-size marker mode (OFF by default; not native Muse tracking)");layout.addView(markerMode);
  markerIdInput=new EditText(this);markerIdInput.setHint("DICT_4X4_50 marker ID (0–49), explicit");markerIdInput.setInputType(2);layout.addView(markerIdInput);
  markerSizeInput=new EditText(this);markerSizeInput.setHint("Measured printed black-square side in millimeters, explicit");markerSizeInput.setInputType(8194);layout.addView(markerSizeInput);
  Button fixture=new Button(this);fixture.setText("Run SYNTHETIC backend fixture (no camera)");fixture.setOnClickListener(v->{if(!capturing)worker.post(()->{try{JSONObject f=MarkerPoseEstimator.syntheticFixture();File temp=new File(getFilesDir(),"synthetic-marker-fixture.json");try(FileOutputStream out=new FileOutputStream(temp)){out.write(f.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}show("Synthetic backend fixture PASS — not a live pose");}catch(Exception|LinkageError e){show("Synthetic backend fixture failed: "+e.getMessage());}});});layout.addView(fixture);
  Button capture=new Button(this);capture.setText("Analyze bright blobs for 20 seconds");capture.setOnClickListener(v->{if(!permitted()){show("Request camera permission first");return;}if(!capturing&&foreground){try{configuredMarkerId=null;configuredMarkerSide=0;if(markerMode.isChecked()){int id=Integer.parseInt(markerIdInput.getText().toString().trim());double side=Double.parseDouble(markerSizeInput.getText().toString().trim())/1000;if(id<0||id>=50||!Double.isFinite(side)||side<.005||side>.5)throw new IllegalArgumentException("Enter ID0–49 and measured black-square side5–500mm");configuredMarkerId=id;configuredMarkerSide=side;}}catch(Exception e){show("Marker mode requires explicit valid ID and measured side; no camera opened");return;}long token=++generation;capturing=true;worker.post(()->begin(token));}});layout.addView(capture);
  Button stop=new Button(this);stop.setText("Stop capture");stop.setOnClickListener(v->stop("user-stopped"));layout.addView(stop);
  status=new TextView(this);status.setText("Idle — explicit permission and capture required");layout.addView(status);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(layout);setContentView(scroll);
 }
 private void show(String value){ui.post(()->{if(status!=null)status.setText(value);});}
 private boolean permissionExists(String name){try{getPackageManager().getPermissionInfo(name,0);return true;}catch(PackageManager.NameNotFoundException e){return false;}}
 private boolean permitted(){return checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED&&(!permissionExists(HEADSET)||checkSelfPermission(HEADSET)==PackageManager.PERMISSION_GRANTED);}
 private void requestAndEnumerate(){if(capturing)return;List<String> names=new ArrayList<>();names.add(Manifest.permission.CAMERA);if(permissionExists(HEADSET))names.add(HEADSET);if(permitted())worker.post(this::enumerate);else requestPermissions(names.toArray(new String[0]),7);}
 @Override public void onRequestPermissionsResult(int code,String[] names,int[] grants){super.onRequestPermissionsResult(code,names,grants);if(code==7){if(permitted())worker.post(this::enumerate);else show("Camera permission denied; no camera opened");}}
 private static Object value(Object v)throws JSONException {if(v==null)return JSONObject.NULL;if(v.getClass().isArray())return new JSONArray(v);if(v instanceof Number||v instanceof Boolean||v instanceof String)return v;return v.toString();}
 private <T> void characteristic(JSONObject out,CameraCharacteristics c,CameraCharacteristics.Key<T> key){try{out.put(key.getName(),value(c.get(key)));}catch(Exception e){try{out.put(key.getName()+"Error",e.getClass().getSimpleName());}catch(JSONException ignored){}}}
 private JSONArray inventory()throws Exception {
  JSONArray list=new JSONArray();for(String id:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(id);JSONObject o=new JSONObject();o.put("cameraId",id);characteristic(o,c,SOURCE);characteristic(o,c,POSITION);characteristic(o,c,CameraCharacteristics.LENS_INTRINSIC_CALIBRATION);characteristic(o,c,CameraCharacteristics.LENS_DISTORTION);characteristic(o,c,CameraCharacteristics.LENS_POSE_ROTATION);characteristic(o,c,CameraCharacteristics.LENS_POSE_TRANSLATION);characteristic(o,c,CameraCharacteristics.LENS_POSE_REFERENCE);characteristic(o,c,CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE);characteristic(o,c,CameraCharacteristics.SENSOR_INFO_ACTIVE_ARRAY_SIZE);characteristic(o,c,CameraCharacteristics.SENSOR_ORIENTATION);characteristic(o,c,CameraCharacteristics.INFO_SUPPORTED_HARDWARE_LEVEL);
   JSONArray vendorKeys=new JSONArray();for(CameraCharacteristics.Key<?> k:c.getKeys())if(k.getName().startsWith("com.meta.extra_metadata."))vendorKeys.put(k.getName());o.put("metaVendorKeyNames",vendorKeys);
   JSONArray sizes=new JSONArray();StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size[] supported=map==null?null:map.getOutputSizes(ImageFormat.YUV_420_888);if(supported!=null)for(Size z:supported)sizes.put(new JSONArray(new int[]{z.getWidth(),z.getHeight()}));o.put("yuv420Sizes",sizes);list.put(o);
  }return list;
 }
 private void enumerate(){try{receipt=new JSONObject();receipt.put("schemaVersion",1);receipt.put("phase","enumerated");receipt.put("apiLevel",Build.VERSION.SDK_INT);receipt.put("model",Build.MODEL);receipt.put("cameraPermission",checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED);receipt.put("headsetPermissionDeclaredByOS",permissionExists(HEADSET));receipt.put("headsetPermissionGranted",checkSelfPermission(HEADSET)==PackageManager.PERMISSION_GRANTED);receipt.put("cameras",inventory());JSONArray concurrent=new JSONArray();if(Build.VERSION.SDK_INT>=30)for(Set<String> ids:manager.getConcurrentCameraIds())concurrent.put(new JSONArray(ids));receipt.put("concurrentCameraIdSets",concurrent);receipt.put("roomFramesPersisted",false);receipt.put("poseEstablished",false);persist();show("Enumerated "+receipt.getJSONArray("cameras").length()+" cameras; no camera opened");}catch(Exception e){fail("enumerate",e);}}
 private boolean live(long token){return foreground&&capturing&&generation==token;}
 private void begin(long token){if(!live(token))return;closeResources();try{
  enumerate();String selected=null;Size size=null;
  for(String id:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(id);Integer source;try{source=c.get(SOURCE);}catch(IllegalArgumentException e){continue;}if(source==null||source!=0)continue;
   StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size[] sizes=map==null?null:map.getOutputSizes(ImageFormat.YUV_420_888);if(sizes==null)continue;
   for(Size s:sizes)if(s.getWidth()<=1280&&s.getHeight()<=960&&(size==null||(configuredMarkerId==null?(long)s.getWidth()*s.getHeight()<(long)size.getWidth()*size.getHeight():(long)s.getWidth()*s.getHeight()>(long)size.getWidth()*size.getHeight()))){selected=id;size=s;}
   if(selected!=null)break;
  }
  if(selected==null||size==null)throw new IllegalStateException("No tagged public passthrough YUV camera within analysis bounds");
  captureCharacteristics=manager.getCameraCharacteristics(selected);markerEstimator=configuredMarkerId==null?null:new MarkerPoseEstimator(configuredMarkerId,configuredMarkerSide);matchedResults.clear();
  receipt.put("optionalMarkerMode",configuredMarkerId!=null);receipt.put("markerMaxImageAgeMs",500);receipt.put("markerMaxFutureMs",5);receipt.put("markerRequiredTimestampSource","REALTIME");receipt.put("configuredMarkerId",configuredMarkerId==null?JSONObject.NULL:configuredMarkerId);receipt.put("measuredBlackSideMeters",configuredMarkerId==null?JSONObject.NULL:configuredMarkerSide);receipt.put("currentMarkerPose",JSONObject.NULL);receipt.put("worldPoseEstablished",false);receipt.put("musePoseEstablished",false);
  frames=new JSONArray();received=processed=0;latestResult=new JSONObject();startNs=SystemClock.elapsedRealtimeNanos();lastProcessedNs=0;receipt.put("selectedCameraId",selected);receipt.put("width",size.getWidth());receipt.put("height",size.getHeight());receipt.put("startedWallTimeMs",System.currentTimeMillis());receipt.put("startElapsedRealtimeNanos",startNs);receipt.put("durationLimitMs",20000);receipt.put("threshold",BrightBlobDetector.THRESHOLD);receipt.put("sampleStep",BrightBlobDetector.STEP);receipt.put("maxRetainedFrames",100);receipt.put("phase","opening");persist();
  reader=ImageReader.newInstance(size.getWidth(),size.getHeight(),ImageFormat.YUV_420_888,2);reader.setOnImageAvailableListener(r->analyze(r,token),worker);ui.postDelayed(deadline,20000);if(markerEstimator!=null)ui.postDelayed(poseFreshness,500);
  pendingOpens++;try{manager.openCamera(selected,new CameraDevice.StateCallback(){private boolean pending=true;private void releasePending(){if(pending){pending=false;pendingOpens--;}maybeQuitWorker();}public void onOpened(CameraDevice d){if(!live(token)){d.close();releasePending();return;}camera=d;releasePending();try{d.createCaptureSession(Collections.singletonList(reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){if(!live(token)){s.close();return;}session=s;try{CaptureRequest.Builder q=d.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);q.addTarget(reader.getSurface());if(markerEstimator!=null){q.set(CaptureRequest.DISTORTION_CORRECTION_MODE,CaptureRequest.DISTORTION_CORRECTION_MODE_OFF);q.set(CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE,CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE_OFF);q.set(CaptureRequest.LENS_OPTICAL_STABILIZATION_MODE,CaptureRequest.LENS_OPTICAL_STABILIZATION_MODE_OFF);if(Build.VERSION.SDK_INT>=30)q.set(CaptureRequest.CONTROL_ZOOM_RATIO,1f);if(Build.VERSION.SDK_INT>=31)q.set(CaptureRequest.SCALER_ROTATE_AND_CROP,CaptureRequest.SCALER_ROTATE_AND_CROP_NONE);}s.setRepeatingRequest(q.build(),new CameraCaptureSession.CaptureCallback(){@Override public void onCaptureCompleted(CameraCaptureSession ss,CaptureRequest request,TotalCaptureResult result){if(live(token))recordResult(result);}},worker);receipt.put("phase","capturing");persist();show("Capturing bounded bright-blob statistics; no images saved");}catch(Exception e){fail("repeat",e);stop("capture-error");}}public void onConfigureFailed(CameraCaptureSession s){s.close();if(live(token)){fail("configure",new IllegalStateException("Session configuration failed"));stop("configure-error");}}},worker);}catch(Exception e){fail("session",e);stop("session-error");}}public void onDisconnected(CameraDevice d){d.close();releasePending();if(live(token))stop("camera-disconnected");}public void onError(CameraDevice d,int error){d.close();releasePending();if(live(token)){fail("camera",new IllegalStateException("Camera error "+error));stop("camera-error");}}},worker);}catch(Exception e){pendingOpens--;throw e;}
 }catch(Exception e){fail("open",e);stop("open-error");}}
 private void recordResult(TotalCaptureResult result){Long stamp=result.get(CaptureResult.SENSOR_TIMESTAMP);if(stamp!=null){matchedResults.put(stamp,result);while(matchedResults.size()>8)matchedResults.pollFirstEntry();}try{JSONObject o=new JSONObject();o.put("sensorTimestampNanos",value(result.get(CaptureResult.SENSOR_TIMESTAMP)));o.put("exposureNanos",value(result.get(CaptureResult.SENSOR_EXPOSURE_TIME)));o.put("sensitivity",value(result.get(CaptureResult.SENSOR_SENSITIVITY)));o.put("cropRegion",value(result.get(CaptureResult.SCALER_CROP_REGION)));latestResult=o;}catch(JSONException ignored){}}
 private void analyze(ImageReader r,long token){Image image=null;try{image=r.acquireLatestImage();if(image==null)return;received++;if(!live(token))return;long now=SystemClock.elapsedRealtimeNanos();if(now-startNs>=20000000000L){stop("completed-deadline");return;}if(now-lastProcessedNs<200000000L||processed>=100)return;lastProcessedNs=now;
  Image.Plane y=image.getPlanes()[0];BrightBlobDetector.Result blobs=BrightBlobDetector.analyze(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight());JSONObject o=new JSONObject();o.put("sequence",processed++);o.put("imageTimestampNanos",image.getTimestamp());o.put("callbackElapsedRealtimeNanos",now);o.put("elapsedMs",(now-startNs)/1000000);o.put("brightSamples",blobs.brightSamples);o.put("totalSamples",blobs.totalSamples);o.put("captureResultLatestNotGuaranteedMatched",new JSONObject(latestResult.toString()));JSONArray list=new JSONArray();for(BrightBlobDetector.Blob b:blobs.blobs){JSONObject a=new JSONObject();a.put("sampleCount",b.count);a.put("centroidX",b.x);a.put("centroidY",b.y);list.put(a);}o.put("blobs",list);if(markerEstimator!=null){JSONObject marker;TotalCaptureResult exact=matchedResults.remove(image.getTimestamp());try{if(exact==null)throw new IllegalArgumentException("No exact SENSOR_TIMESTAMP capture result");long imageAge=markerFrameAge(image.getTimestamp());CameraCalibration calibration=markerCalibration(exact,image.getWidth(),image.getHeight());marker=markerEstimator.analyze(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight(),calibration);markerFrameAge(image.getTimestamp());marker.put("imageAgeAtPoseStartNanos",imageAge);marker.put("matchedSensorTimestampNanos",exact.get(CaptureResult.SENSOR_TIMESTAMP));}catch(Exception e){marker=new JSONObject().put("phase","unavailable").put("reason",e.getMessage()).put("currentPose",JSONObject.NULL);}o.put("marker",marker);receipt.put("currentMarkerPose","camera-relative-marker-pose".equals(marker.optString("phase"))?marker:JSONObject.NULL);}frames.put(o);receipt.put("framesReceived",received);receipt.put("framesAnalyzed",processed);receipt.put("frames",frames);persist();String text="Frames analyzed: "+processed+"; bright components: "+list.length()+" — unclassified";if(markerEstimator!=null){JSONObject m=o.getJSONObject("marker");text="Marker "+m.optString("phase")+": "+m.optString("reason");if("camera-relative-marker-pose".equals(m.optString("phase")))text="CAMERA-relative marker t(m): "+m.getJSONArray("translationMeters")+" RMS(px): "+m.getDouble("reprojectionRmsPixels")+"; not world/Muse pose";}show(text);
 }catch(Exception e){if(live(token)){fail("analysis",e);stop("analysis-error");}}finally{if(image!=null)image.close();}}
 private void fail(String stage,Exception e){try{receipt.put("errorStage",stage);receipt.put("error",e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));persist();}catch(JSONException ignored){}show(stage+": "+e.getClass().getSimpleName());}
 private void persist(){try{File temp=new File(getFilesDir(),"optical-observation.tmp"),target=new File(getFilesDir(),"optical-observation.json");try(FileOutputStream f=new FileOutputStream(temp)){f.write(receipt.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}if(!temp.renameTo(target))throw new IOException("Atomic receipt rename failed");}catch(IOException e){show("Receipt persistence failed: "+e.getClass().getSimpleName());}}
 private static int[] rect(android.graphics.Rect r){return r==null?null:new int[]{r.left,r.top,r.right,r.bottom};}
 private long markerFrameAge(long imageTimestamp){
  Integer source=captureCharacteristics.get(CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE);
  return FrameFreshness.imageAge(source!=null&&source==CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE_REALTIME,imageTimestamp,SystemClock.elapsedRealtimeNanos());
 }
 private CameraCalibration markerCalibration(TotalCaptureResult result,int width,int height){
  Integer distortion=result.get(CaptureResult.DISTORTION_CORRECTION_MODE),video=result.get(CaptureResult.CONTROL_VIDEO_STABILIZATION_MODE),optical=result.get(CaptureResult.LENS_OPTICAL_STABILIZATION_MODE);
  if(distortion==null||distortion!=0||video==null||video!=0||optical==null||optical!=0)throw new IllegalArgumentException("Unknown/non-OFF distortion or stabilization mode");
  if(Build.VERSION.SDK_INT>=31){Integer rotate=result.get(CaptureResult.SCALER_ROTATE_AND_CROP);if(rotate==null||rotate!=0)throw new IllegalArgumentException("Unknown/rotated image coordinates");}
  if(Build.VERSION.SDK_INT>=30){Float zoom=result.get(CaptureResult.CONTROL_ZOOM_RATIO);if(zoom==null||Math.abs(zoom-1)>1e-5)throw new IllegalArgumentException("Unknown/nonunit zoom ratio");}
  Float focus=captureCharacteristics.get(CameraCharacteristics.LENS_INFO_MINIMUM_FOCUS_DISTANCE);float[] intrinsic=result.get(CaptureResult.LENS_INTRINSIC_CALIBRATION),coefficients=result.get(CaptureResult.LENS_DISTORTION);
  if(focus!=null&&focus==0){if(intrinsic==null)intrinsic=captureCharacteristics.get(CameraCharacteristics.LENS_INTRINSIC_CALIBRATION);if(coefficients==null)coefficients=captureCharacteristics.get(CameraCharacteristics.LENS_DISTORTION);}
  return CameraCalibration.from(intrinsic,coefficients,rect(captureCharacteristics.get(CameraCharacteristics.SENSOR_INFO_PRE_CORRECTION_ACTIVE_ARRAY_SIZE)),rect(result.get(CaptureResult.SCALER_CROP_REGION)),width,height);
 }
 private void maybeQuitWorker(){if(destroying&&pendingOpens==0&&thread!=null)thread.quitSafely();}
 private void closeResources(){matchedResults.clear();if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(reader!=null){reader.close();reader=null;}}
 private void stop(String reason){capturing=false;++generation;ui.removeCallbacks(deadline);ui.removeCallbacks(poseFreshness);if(worker!=null)worker.post(()->{closeResources();try{receipt.put("phase",reason);receipt.put("currentMarkerPose",JSONObject.NULL);receipt.put("framesReceived",received);receipt.put("framesAnalyzed",processed);receipt.put("stoppedWallTimeMs",System.currentTimeMillis());persist();}catch(JSONException ignored){}show("Stopped: "+reason+"; frames analyzed: "+processed);maybeQuitWorker();});}
 @Override protected void onResume(){super.onResume();foreground=true;}
 @Override protected void onPause(){foreground=false;stop("backgrounded");super.onPause();}
 @Override protected void onDestroy(){destroying=true;foreground=false;stop("destroyed");super.onDestroy();}
}
